def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node must not be None")
    try:
        children = list(node)
    except TypeError:
        raise TypeError("node must be an XML element with iterable children")
    result = {}
    for child in children:
        result[child.tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        # Ensure expected keys
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        if not isinstance(aliases, list):
            aliases = [aliases]
        if not isinstance(links, list):
            links = [links]
        return {"subject": subject, "aliases": aliases, "links": links}
    except json.JSONDecodeError:
        pass  # fall back to XRD

    # Try XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        # Extract namespace if present
        ns = ""
        if root.tag.startswith("{"):
            ns = root.tag[1:root.tag.index("}")]
        def qname(tag):
            return f"{{{ns}}}{tag}" if ns else tag

        subject_elem = root.find(qname("Subject"))
        subject = subject_elem.text if subject_elem is not None else None

        alias_elems = root.findall(qname("Alias"))
        aliases = [e.text for e in alias_elems if e.text]

        link_elems = root.findall(qname("Link"))
        links = []
        for link in link_elems:
            # Include all attributes of the Link element
            link_dict = {k: v for k, v in link.attrib.items()}
            links.append(link_dict)

        return {"subject": subject, "aliases": aliases, "links": links}
    except ET.ParseError as e:
        raise ValueError("Invalid webfinger format: unable to parse as JSON or XRD") from e
    except Exception as e:
        raise ValueError(f"Error parsing webfinger: {e}") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    from urllib.error import URLError, HTTPError

    if not isinstance(handle, str):
        raise ValueError("Handle must be a string")

    # Strip optional 'acct:' prefix
    if handle.lower().startswith("acct:"):
        handle = handle[5:]

    if "@" not in handle:
        raise ValueError("Handle must be in the form 'user@domain'")

    localpart, domain = handle.split("@", 1)
    if not localpart or not domain:
        raise ValueError("Handle must contain both user and domain parts")

    resource = f"acct:{handle}"
    query = urllib.parse.urlencode({"resource": resource})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise ValueError(f"HTTP error {response.status} when retrieving webfinger for {handle}")
            data_bytes = response.read()
            data_str = data_bytes.decode("utf-8")
            try:
                data = json.loads(data_str)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON from webfinger response for {handle}: {e}") from e
            return data
    except HTTPError as e:
        raise ValueError(f"HTTP error {e.code} when retrieving webfinger for {handle}") from e
    except URLError as e:
        raise ValueError(f"URL error when retrieving webfinger for {handle}: {e}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error when retrieving webfinger for {handle}: {e}") from e

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    url = f"https://{host}/.well-known/host-meta"
    urllib_request = __import__('urllib.request')
    try:
        with urllib_request.urlopen(url, timeout=10) as resp:
            data = resp.read()
    except Exception as e:
        raise RuntimeError(f"Error retrieving host-meta from {host}: {e}") from e
    try:
        return XRD.fromstring(data)
    except Exception as e:
        raise RuntimeError(f"Failed to parse host-meta from {host}: {e}") from e

