        env_var = 'CONFIG_PATH'
        if env_var not in os.environ:
            base_dir = os.path.dirname(__file__) if '__file__' in globals() else os.getcwd()
            default_path = os.path.join(base_dir, 'config.json')
            os.environ[env_var] = default_path
    except NameError:
        # os module or __file__ not available; ignore
        pass
    except Exception:
        # any other error; ignore
        pass
